WITH rollup_totals AS (SELECT p.status AS order_status, a.status AS shipment_status, COUNT(*) AS cnt, MAX(a.cost) AS max_cost, GROUPING_ID() AS gid FROM shipments a LEFT JOIN orders p ON a.order_id = p.id GROUP BY GROUPING SETS ((p.status, a.status), (p.status), ())) SELECT shipment_status, cnt, max_cost, gid, CASE WHEN shipment_status RLIKE '^(LOST|DELIVERED)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS shipment_status_zone FROM rollup_totals ORDER BY gid DESC
